# -*- coding: utf-8 -*-
import json
w=json.load(open('words.json',encoding='utf-8'))
phr=u"""Я удалил все планеры и задачники,|и вот почему.|На их заполнение уходит много времени,|просто каждое дело превращается|в отдельную задачу.|Открыть календарь,|нажать плюс,|вписать название,|выбрать время,|поставить напоминание,|сохранить.|Один созвон|и это уже семь нажатий.|И после очередного|удалённого приложения|до меня дошло.|Нужен планер с задачами|и встроенной нейросетью|для быстрой записи.|И без тупых вопросов,|какое у меня эмоциональное состояние.|Поэтому я сделал свой.|Сказал задачу:|«Созвон завтра с трёх до четырёх.|Напомни за час.»|Всё,|он сам понимает|дату, время, напоминание.|Для меня это стало частью жизни.|Причина простая.|Я делал его под свою проблему.|Хочешь протестировать?|Пиши «план»,|я отправлю тебе ссылку.""".split('|')
key=set(u"удалил планеры задачники почему времени каждое задачу Открыть плюс название время напоминание сохранить семь нажатий приложения дошло задачами нейросетью быстрой тупых эмоциональное свой Всё сам дату жизни простая проблему протестировать план ссылку".split())
toks=[(pi,t) for pi,p in enumerate(phr) for t in p.split()]
assert len(toks)==len(w),(len(toks),len(w))
out=[]
for (pi,t),x in zip(toks,w):
    bare=t.strip(u'.,:;?!«»')
    out.append({'t':t,'s':x['s'],'e':x['e'],'p':pi,'k':bare in key})
out[0]['s']=0.74
open('timeline.js','w',encoding='utf-8').write('window.WORDS='+json.dumps(out,ensure_ascii=False)+';\nwindow.RMS='+open('rms.json').read().strip()+';\n')
print(len(out), 'phrases', len(phr))
